#include "Player.h"
#include "Resample.h"
#include "../services/Diagnostics.h"
#include <atomic>
#include <condition_variable>
#include <deque>
#include <future>
#include <mutex>
#include <thread>
namespace phthongos::audio {
namespace {
using juce::var;using juce::String;
var obj(std::initializer_list<std::pair<const char*,var>> xs){auto* o=new juce::DynamicObject;for(auto& x:xs)o->setProperty(x.first,x.second);return var(o);}
var integer(std::uint64_t x){return var(static_cast<juce::int64>(x));}
float gain(float db){if(!std::isfinite(db)||db< -60||db>12)throw std::invalid_argument("Volume invalide.");return db<=-60?0:std::pow(10.f,db/20.f);}
}
struct Player::Impl:juce::AudioIODeviceCallback {
 juce::File piano,speex;std::function<juce::File()> bank;juce::AudioDeviceManager devices;std::thread worker;
 std::mutex mutex,deviceMutex,reportMutex;std::condition_variable wake;bool stopping=false;std::deque<std::function<void()>> tasks;
 juce::File sourceFile;double sourceDuration=0;std::vector<Note> loadedNotes;std::map<int,float> voiceLevels;
 std::unique_ptr<Engine> engine;juce::var selected;String deviceName,error;std::atomic<unsigned> deviceRate{48000},bufferFrames{512};std::atomic<bool> deviceRunning{false};
 std::atomic<std::uint64_t> epoch{0},currentId{0},consumedPosition{0},consumedCount{0},consumedEpoch{0},clipped{0},keyLow{0},keyHigh{0};std::atomic<bool> consumedPlaying{false};std::atomic<double> lastRecovery{0};
 std::atomic<unsigned> clockSequence{0};std::atomic<double> clockAt{0},clockPosition{0},clockCount{0};std::atomic<std::uint64_t> clockEpoch{0};
 struct Frame {std::array<float,2> sample;std::uint64_t epoch,position,id,low,high,clipped,count;bool playing;};
 std::array<float,2> lastOutput{},deviceFadeFrom{};unsigned deviceFadeLeft=0,deviceFadeTotal=1;std::uint64_t outputEpoch=0;bool outputAvailable=false;
 static constexpr std::size_t capacity=4096;std::array<Frame,capacity> ring{};std::atomic<std::uint64_t> written{0},read{0};
 Impl(juce::File p,juce::File s,std::function<juce::File()> b):piano(std::move(p)),speex(std::move(s)),bank(std::move(b)){worker=std::thread([this]{run();});devices.addAudioCallback(this);}
 ~Impl(){devices.removeAudioCallback(this);devices.closeAudioDevice();{std::lock_guard<std::mutex> l(mutex);stopping=true;}wake.notify_one();if(worker.joinable())worker.join();}
 template<class F>auto submit(const char* name,F f)->decltype(f()){
  auto trace=std::make_shared<diagnostics::Span>(juce::String("audio/task/")+name,juce::String(name)!="snapshot");trace->phase("queued");using R=decltype(f());auto task=std::make_shared<std::packaged_task<R()>>(std::move(f));auto result=task->get_future();{std::lock_guard<std::mutex> l(mutex);tasks.push_back([task,trace]{trace->phase("running");(*task)();});}wake.notify_one();return result.get();
 }
 void run(){while(true){std::deque<std::function<void()>> pending;{std::unique_lock<std::mutex> l(mutex);if(tasks.empty()&&!stopping)wake.wait_for(l,std::chrono::milliseconds(2));if(stopping)break;pending.swap(tasks);}for(auto& f:pending)f();
  if(!engine||!deviceRunning.load())continue;auto write=written.load(std::memory_order_relaxed),end=read.load(std::memory_order_acquire)+std::min<std::size_t>(capacity,1024);if(write>=end)continue;
  auto generation=epoch.load();while(write<end){auto sample=engine->next();auto keys=engine->keys();std::uint64_t lo=0,hi=0;for(unsigned p=0;p<64;++p){if(keys[p])lo|=std::uint64_t(1)<<p;if(keys[p+64])hi|=std::uint64_t(1)<<p;}
    ring[write%capacity]={sample,generation,engine->position,engine->id,lo,hi,engine->clipped,engine->countRemaining,engine->playing};++write;}
  written.store(write,std::memory_order_release);
 }}
 void open(){diagnostics::Span trace("audio/open-device");std::lock_guard<std::mutex> l(deviceMutex);if(devices.getCurrentAudioDevice()&&deviceRunning.load())return;auto result=devices.initialise(0,2,nullptr,true);if(result.isNotEmpty()){{std::lock_guard<std::mutex> report(reportMutex);error=result;}throw std::runtime_error(result.toStdString());}auto* d=devices.getCurrentAudioDevice();if(!d)throw std::runtime_error("Sortie audio indisponible.");{std::lock_guard<std::mutex> report(reportMutex);deviceName=d->getName();error={};}}
 void require(std::uint64_t id){if(!engine||engine->id!=id)throw std::invalid_argument("Player non préparé pour cet audio.");}
 void resetReport(){consumedPosition=engine->position;consumedCount=engine->countRemaining;consumedPlaying=engine->playing;currentId=engine->id;keyLow=0;keyHigh=0;clipped=engine->clipped;}
 void invalidate(){++epoch;resetReport();}
 void build(){auto rate=deviceRate.load();auto* old=engine.get();auto sound=bank();auto made=std::make_unique<Engine>(rate,std::make_unique<Sampler>(piano,sound,rate),std::make_unique<Sampler>(piano,sound,rate));
  if(old){made->id=old->id;made->version=old->version;made->pcm=old->rate==rate?old->pcm:std::make_shared<const analysis::StereoPcm>(sourceFile!=juce::File()?readStereo(sourceFile,rate,speex):analysis::StereoPcm(std::size_t(std::ceil(sourceDuration*rate)),{0.f,0.f}));double end=double(made->pcm->size())/rate;for(auto& n:loadedNotes)end=std::max(end,double(n.end));if(std::ceil(end*rate)>made->pcm->size()){auto copy=std::make_shared<analysis::StereoPcm>(*made->pcm);copy->resize(std::size_t(std::ceil(end*rate)),{0.f,0.f});made->pcm=copy;}made->click.configure(rate,old->click.enabled,old->click.gain<=0?-60:20*std::log10(old->click.gain),old->click.grid);made->levels(voiceLevels);made->mode=old->mode;made->audioGain=old->audioGain;made->midiGain=old->midiGain;made->setReverb(old->reverb);made->notes(loadedNotes);made->seek(std::uint64_t(std::round(double(consumedPosition.load())/old->rate*rate)));}engine=std::move(made);
 }
 void audioDeviceIOCallbackWithContext(const float* const*,int,float* const* outputs,int channels,int count,const juce::AudioIODeviceCallbackContext&)override{
  const double callbackAt=juce::Time::getMillisecondCounterHiRes()/1000.;int lastConsumed=-1;
  auto cursor=read.load(std::memory_order_relaxed);auto limit=written.load(std::memory_order_acquire);auto generation=epoch.load(std::memory_order_acquire);
  for(int i=0;i<count;++i){while(cursor<limit&&ring[cursor%capacity].epoch!=generation)++cursor;std::array<float,2> value{};
   if(cursor<limit){const auto& f=ring[cursor%capacity];value=f.sample;consumedPosition.store(f.position,std::memory_order_relaxed);consumedCount.store(f.count,std::memory_order_relaxed);currentId.store(f.id,std::memory_order_relaxed);consumedPlaying.store(f.playing,std::memory_order_relaxed);keyLow.store(f.low,std::memory_order_relaxed);keyHigh.store(f.high,std::memory_order_relaxed);clipped.store(f.clipped,std::memory_order_relaxed);consumedEpoch.store(f.epoch,std::memory_order_release);lastConsumed=i;++cursor;}
   bool available=lastConsumed==i;
   if(outputEpoch!=generation||available!=outputAvailable){outputEpoch=generation;outputAvailable=available;deviceFadeFrom=lastOutput;deviceFadeTotal=std::max(deviceRate.load()/500,1u);deviceFadeLeft=deviceFadeTotal;}
   if(deviceFadeLeft){float mix=1.f-float(deviceFadeLeft)/deviceFadeTotal;for(int c=0;c<2;++c)value[c]=deviceFadeFrom[c]*(1.f-mix)+value[c]*mix;--deviceFadeLeft;}lastOutput=value;
   for(int c=0;c<channels;++c)if(outputs[c])outputs[c][i]=value[std::min(c,1)];
  }read.store(cursor,std::memory_order_release);
  if(lastConsumed>=0){clockSequence.fetch_add(1,std::memory_order_acq_rel);clockPosition.store(double(consumedPosition.load())/deviceRate.load(),std::memory_order_relaxed);clockAt.store(callbackAt+double(lastConsumed+1)/deviceRate.load(),std::memory_order_relaxed);clockCount.store(double(consumedCount.load())/deviceRate.load(),std::memory_order_relaxed);clockEpoch.store(generation,std::memory_order_relaxed);clockSequence.fetch_add(1,std::memory_order_release);}
 }
 void audioDeviceAboutToStart(juce::AudioIODevice* d)override{deviceRate=unsigned(std::round(d->getCurrentSampleRate()));bufferFrames=unsigned(d->getCurrentBufferSizeSamples());deviceRunning=true;}
 void audioDeviceStopped()override{deviceRunning=false;}
 void audioDeviceError(const String& message)override{std::lock_guard<std::mutex> l(reportMutex);error=message;deviceRunning=false;}
};
Player::Player(juce::File piano,juce::File speex,std::function<juce::File()> bank):impl(std::make_unique<Impl>(std::move(piano),std::move(speex),std::move(bank))){}
Player::~Player()=default;
void Player::prepare(std::uint64_t id,const juce::File& file,double duration){diagnostics::Span operation("audio/prepare");impl->open();auto rate=impl->deviceRate.load();auto pcm=std::make_shared<const analysis::StereoPcm>(file!=juce::File()?readStereo(file,rate,impl->speex):analysis::StereoPcm(std::size_t(std::ceil(duration*rate)),{0.f,0.f}));impl->submit("prepare",[&,pcm,id]{impl->sourceFile=file;impl->sourceDuration=duration;impl->loadedNotes.clear();impl->voiceLevels.clear();if(!impl->engine||impl->engine->rate!=rate)impl->build();auto& e=*impl->engine;e.midiPanic();e.pause();e.levels({});e.id=id;e.version=0;e.pcm=pcm;e.notes({});e.seek(0);impl->invalidate();});}
void Player::notes(std::uint64_t id,std::uint64_t version,const std::vector<Note>& notes,double timelineDuration){impl->submit("notes",[&]{impl->require(id);auto& e=*impl->engine;if(version<e.version)return;auto position=impl->consumedPosition.load();double end=std::max(double(e.pcm->size())/e.rate,timelineDuration);for(auto& n:notes)end=std::max(end,double(n.end));if(end>1200)throw std::invalid_argument("Durée MIDI au-delà de la limite de lecture (20 minutes).");auto frames=std::size_t(std::ceil(end*e.rate));if(frames>e.pcm->size()){auto copy=std::make_shared<analysis::StereoPcm>(*e.pcm);copy->resize(frames,{0.f,0.f});e.pcm=copy;}e.notes(notes);e.version=version;impl->loadedNotes=notes;e.seek(position);if(e.playing)impl->invalidate();});}
void Player::key(std::uint64_t id,int pitch,unsigned program,float db,std::optional<Part> part){impl->submit("keyboard",[&]{impl->require(id);if(pitch<0)impl->engine->keyUp();else impl->engine->keyDown(impl->engine->auditionProgram(part,program),pitch,90,db);});}
void Player::midi(std::uint64_t id,const String& action,unsigned channel,int pitch,int velocity,unsigned program,float db,std::optional<Part> part){impl->submit("midi-input",[&]{impl->require(id);auto& e=*impl->engine;if(action=="note")e.midiNote(channel,pitch,velocity,e.auditionProgram(part,program),db);else if(action=="sustain")e.midiSustain(channel,velocity>=64);else e.midiPanic();});}
void Player::levels(std::uint64_t id,const std::map<int,float>& levels){impl->submit("voice-levels",[&]{impl->require(id);impl->voiceLevels=levels;impl->engine->levels(levels);});}
void Player::control(std::uint64_t id,const String& command,double position){if(!std::isfinite(position)||position<0)throw std::invalid_argument("Commande player invalide.");impl->submit("control",[&]{impl->require(id);auto& e=*impl->engine;auto action=command=="toggle"?(impl->consumedPlaying.load()?String("pause"):String("play")):command;e.seek(impl->consumedPosition.load());if(action=="play")e.play();else if(action=="pause")e.pause();else if(action=="stop"){e.pause();e.seek(0);}else if(action=="seek")e.seek(std::uint64_t(std::round(position*e.rate)));else throw std::invalid_argument("Commande player invalide.");if(action=="seek"&&!e.playing)impl->resetReport();else impl->invalidate();});}
juce::var Player::record(std::uint64_t id,bool start,double position,unsigned preCount){
 if(!std::isfinite(position)||position<0||position>=1200||preCount>2)throw std::invalid_argument("Position MIDI invalide.");
 impl->submit("record",[&]{impl->require(id);auto& e=*impl->engine;
   if(start){e.recording=true;e.seek(std::uint64_t(std::round(position*e.rate)));e.play();e.preCount(preCount);}
   else{e.seek(impl->consumedPosition.load());e.recording=false;e.pause();}
   impl->invalidate();});
 // Wait off the message/audio threads for the first consumed recording buffer.
 if(start){auto generation=impl->epoch.load();double until=juce::Time::getMillisecondCounterHiRes()+100;
   while(impl->consumedEpoch.load()!=generation&&impl->deviceRunning.load()&&juce::Time::getMillisecondCounterHiRes()<until)juce::Thread::sleep(1);}
 return snapshot();
}
void Player::metronome(std::uint64_t id,bool on,float db,const rhythm::Grid& grid){impl->submit("metronome",[&]{impl->require(id);impl->engine->click.configure(impl->engine->rate,on,db,grid);});}
void Player::mix(std::uint64_t id,unsigned mode,float audioDb,float midiDb){if(mode>2)throw std::invalid_argument("Mode de lecture invalide.");auto a=gain(audioDb),m=gain(midiDb);impl->submit("mix",[&]{impl->require(id);auto& e=*impl->engine;bool changed=e.mode!=mode;e.mode=mode;e.audioGain=a;e.midiGain=m;if(changed){e.seek(impl->consumedPosition.load());impl->invalidate();}});}
void Player::reverb(std::uint64_t id,double amount){if(!std::isfinite(amount)||amount<0||amount>100)throw std::invalid_argument("Niveau de réverbération invalide.");impl->submit("reverb",[&]{impl->require(id);impl->engine->setReverb(unsigned(std::round(amount)));});}
void Player::audition(std::uint64_t id,int pitch,int velocity,unsigned program,std::optional<Part> part){if(pitch<0||pitch>127||velocity<1||velocity>127||program>128)throw std::invalid_argument("Note de préécoute invalide.");impl->submit("audition",[&]{impl->require(id);impl->engine->audition(impl->engine->auditionProgram(part,program),pitch,velocity);/* Keep queued samples: dropping them would break the smoothed pitch transition. */});}
void Player::initialize(std::uint64_t id){impl->submit("initialize",[&]{impl->require(id);impl->engine->seek(impl->consumedPosition.load());impl->invalidate();});}
void Player::reload(){diagnostics::Span operation("audio/reload");impl->submit("reload",[&]{if(impl->engine){impl->build();impl->invalidate();}});}
juce::var Player::snapshot(){if(impl->currentId.load()&&!impl->deviceRunning.load()&&juce::Time::getMillisecondCounterHiRes()-impl->lastRecovery>2000){impl->lastRecovery=juce::Time::getMillisecondCounterHiRes();try{impl->open();impl->submit("snapshot",[&]{if(impl->engine){bool resume=impl->consumedPlaying.load();impl->build();if(resume)impl->engine->play();impl->invalidate();}});}catch(const std::exception& e){std::lock_guard<std::mutex> report(impl->reportMutex);impl->error=String::fromUTF8(e.what());}}return impl->submit("snapshot",[&]{auto& p=*impl;auto* e=p.engine.get();std::lock_guard<std::mutex> report(p.reportMutex);juce::Array<var> keys,active;if(e){auto lo=p.keyLow.load(),hi=p.keyHigh.load();for(unsigned i=0;i<128;++i)if((i<64?lo:hi)&(std::uint64_t(1)<<(i%64)))keys.add(int(i));for(std::size_t i=0;i<p.loadedNotes.size();++i){auto& n=p.loadedNotes[i];auto pos=p.consumedPosition.load();if(std::round(double(n.start)*e->rate)<=pos&&pos<std::round(double(n.end)*e->rate))active.add(int(i));}}
 double at=0,pos=0,count=0;std::uint64_t clockGen=0;for(;;){auto seq=p.clockSequence.load(std::memory_order_acquire);if(seq&1)continue;at=p.clockAt.load(std::memory_order_relaxed);pos=p.clockPosition.load(std::memory_order_relaxed);count=p.clockCount.load(std::memory_order_relaxed);clockGen=p.clockEpoch.load(std::memory_order_relaxed);if(seq==p.clockSequence.load(std::memory_order_acquire))break;}
 if(!e||clockGen!=p.epoch.load()||at<=0){at=juce::Time::getMillisecondCounterHiRes()/1000.;pos=e?double(p.consumedPosition.load())/e->rate:0.;count=e?double(p.consumedCount.load())/e->rate:0.;}
 return obj({{"clock_time",at},{"clock_position",pos},{"count_remaining",count},{"metronome_enabled",e&&e->click.enabled},{"metronome_quarter",e?e->click.grid.tempos.front().quarter:.5},{"recording",e&&e->recording},{"ready",e!=nullptr&&p.deviceRunning.load()},{"audio_id",integer(e?e->id:0)},{"playing",p.consumedPlaying.load()},{"position",e?double(p.consumedPosition.load())/e->rate:0.},{"duration",e?double(e->pcm->size())/e->rate:0.},{"note_count",int(p.loadedNotes.size())},{"active_keys",var(keys)},{"active_note_indices",var(active)},{"sample_rate",int(p.deviceRate.load())},{"latency_ms",1000.*p.bufferFrames.load()/p.deviceRate.load()},{"clipped_samples",integer(p.clipped.load())},{"error",p.error.isEmpty()?var():var(p.error)},{"device",p.deviceName},{"sound_bank",std::any_of(p.loadedNotes.begin(),p.loadedNotes.end(),[](auto& n){return n.part&&!n.part->soundfontPath.empty();})?juce::String::fromUTF8("Banques SF2 par voix"):p.bank()!=juce::File()?juce::String("Piano droit + MuseScore General HQ"):std::any_of(p.loadedNotes.begin(),p.loadedNotes.end(),[](auto& n){return n.part&&n.part->program!=0;})?juce::String::fromUTF8("Banque General MIDI absente · instruments rendus au piano · cliquez ici pour l’installer"):juce::String("Piano droit")}});
 });}
juce::var Player::outputs(){diagnostics::Span operation("audio/outputs");std::lock_guard<std::mutex> l(impl->deviceMutex);juce::Array<var> out;for(auto* type:impl->devices.getAvailableDeviceTypes()){type->scanForDevices();auto names=type->getDeviceNames(false);int def=type->getDefaultDeviceIndex(false);for(int i=0;i<names.size();++i)out.add(obj({{"id",type->getTypeName()+"::"+names[i]},{"name",names[i]},{"is_default",i==def}}));}return obj({{"selected",impl->selected},{"devices",var(out)}});}
void Player::select(const var& selected){diagnostics::Span operation("audio/select");std::lock_guard<std::mutex> l(impl->deviceMutex);if(selected.isVoid()||selected.isUndefined()){impl->devices.closeAudioDevice();auto error=impl->devices.initialise(0,2,nullptr,true);if(error.isNotEmpty())throw std::runtime_error(error.toStdString());impl->selected=selected;if(auto* d=impl->devices.getCurrentAudioDevice()){std::lock_guard<std::mutex> report(impl->reportMutex);impl->deviceName=d->getName();impl->error={};}impl->submit("select",[&]{if(impl->engine){bool resume=impl->consumedPlaying.load();impl->build();if(resume)impl->engine->play();impl->invalidate();}});return;}auto text=selected.toString(),type=text.upToFirstOccurrenceOf("::",false,false),name=text.fromFirstOccurrenceOf("::",false,false);if(type.isEmpty()||name.isEmpty())throw std::invalid_argument("Cette sortie audio n’est plus disponible.");impl->devices.setCurrentAudioDeviceType(type,true);auto setup=impl->devices.getAudioDeviceSetup();setup.outputDeviceName=name;setup.inputChannels.clear();setup.outputChannels.setRange(0,2,true);auto error=impl->devices.setAudioDeviceSetup(setup,true);if(error.isNotEmpty())throw std::runtime_error(error.toStdString());impl->selected=selected;if(auto* d=impl->devices.getCurrentAudioDevice()){std::lock_guard<std::mutex> report(impl->reportMutex);impl->deviceName=d->getName();impl->error={};}impl->submit("select",[&]{if(impl->engine){bool resume=impl->consumedPlaying.load();impl->build();if(resume)impl->engine->play();impl->invalidate();}});}
}
